package com.servicehub.security;
import com.servicehub.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.context.annotation.*; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.util.*;
@Configuration public class SecurityConfig { @Bean SecurityFilterChain chain(HttpSecurity http, JwtService jwt, UserRepository users)throws Exception{return http.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/swagger-ui/**","/v3/api-docs/**").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(new JwtFilter(jwt,users), UsernamePasswordAuthenticationFilter.class).build();} static class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepository users; JwtFilter(JwtService j,UserRepository u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader(HttpHeaders.AUTHORIZATION);if(h!=null&&h.startsWith("Bearer "))try{var u=users.findByEmail(jwt.subject(h.substring(7))).orElseThrow();var a=new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole())));org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){}c.doFilter(r,s);} } }
